  "@type": "FAQPage",
  "inLanguage": "en",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do you check a supplier's certificate of analysis before you buy?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Check that the certificate names the manufacturer and its site, that the batch number, dates and quantity match the goods offered, and that every test and acceptance criterion matches your agreed specification and pharmacopoeial edition. Then confirm a named quality unit released it, compare it with earlier batches, and ask the manufacturer to confirm it directly."
      }
    },
    {
      "@type": "Question",
      "name": "Can a genuine certificate of analysis still be the wrong one?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. A certificate can be authentic and still describe a different batch, a different grade or a different manufacturing site from the material you are being offered. Match the batch number, product name, grade and site against the invoice, the labels and the GMP certificate before relying on any result printed on it."
      }
    },
    {
      "@type": "Question",
      "name": "Is a certificate that says complies for every test enough?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Usually not. Where a test produces a number, such as assay, water content or a named impurity, the certificate should report the number. A column of complies hides how close the batch sits to its acceptance criteria and makes it impossible to compare one batch with the next. Ask for the actual results."
      }
    },
    {
      "@type": "Question",
      "name": "How do I confirm a certificate with the manufacturer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Find the manufacturer's contact details independently, from its own website, its registration or a previous verified contact, not from the certificate itself. Send the batch number, the certificate number and a copy of the document, and ask the quality unit to confirm that it issued it and that the results match its records."
      }
    },
    {
      "@type": "Question",
      "name": "Should I test the material myself if the certificate looks right?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For a first order or a new supplier, independent testing against your own specification is a sensible check. It confirms that the material matches the certificate, not only that the certificate matches the specification. Over time, periodic testing of selected batches shows whether the supplier's certificates remain reliable."
      }
    }
  ]
